package com.gorsok.toolkitpanel;

import com.gorsok.toolkitexporter.OsrsToolkitExporterPlugin;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Author's dev launcher: the whole OSRS Toolkit suite (this Panel + OSRS Toolkit Exporter) in one client.
 * Only compiled when the Exporter project sits next to this one (see build.gradle); not part of the plugin.
 */
public class DevLauncher
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ToolkitPanelPlugin.class, OsrsToolkitExporterPlugin.class);
		RuneLite.main(args);
	}
}

package com.gorsok.toolkitpanel;

import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

class BondInfoBox extends InfoBox
{
	private volatile ToolkitSnapshot snap;

	BondInfoBox(BufferedImage image, Plugin plugin)
	{
		super(image, plugin);
	}

	void setSnapshot(ToolkitSnapshot s)
	{
		snap = s;
	}

	@Override
	public String getText()
	{
		ToolkitSnapshot s = snap;
		return s == null || s.bondPct == null ? "?" : Math.round(s.bondPct) + "%";
	}

	@Override
	public Color getTextColor()
	{
		ToolkitSnapshot s = snap;
		return s != null && s.bondPct != null && s.bondPct >= 100 ? new Color(0x4CAF7D) : Color.WHITE;
	}

	@Override
	public String getTooltip()
	{
		ToolkitSnapshot s = snap;
		if (s == null || s.bondPct == null)
		{
			return "OSRS Toolkit";
		}
		return Text.t("bond") + ": " + Text.pct(s.bondPct) + " %</br>" + Text.t("bond_line", Text.gp(s.cash), Text.gp(s.bondPrice));
	}
}

package com.gorsok.toolkitpanel;

/** Range of the GE price chart. Public top-level enum: RuneLite's config proxy must be able to see it. */
public enum ChartRange
{
	DAY("5m", 24 * 3600L, "24h", "24 h"),
	WEEK("1h", 7 * 86400L, "7d", "7 j"),
	MONTH("6h", 30 * 86400L, "30d", "30 j");

	final String timestep;
	final long seconds;
	private final String en, fr;

	ChartRange(String timestep, long seconds, String en, String fr)
	{
		this.timestep = timestep;
		this.seconds = seconds;
		this.en = en;
		this.fr = fr;
	}

	String label()
	{
		return Text.fr ? fr : en;
	}

	@Override
	public String toString()
	{
		return en;
	}
}

package com.gorsok.toolkitpanel;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** Small price box shown while you set up a GE offer. Alt-drag to move it. */
class GeHelperOverlay extends OverlayPanel
{
	// Raw ids (stable for years) so the plugin doesn't depend on renamed API constants.
	private static final int GE_GROUP = 465;            // Grand Exchange interface
	private static final int VARP_GE_ITEM = 1151;       // item being set up (-1 = none)
	private static final int VARBIT_QUANTITY = 4396;
	private static final int VARBIT_TYPE = 4397;        // 0 = buy, 1 = sell
	// The typed price of a NEW offer: a 64-bit varp since the Beyond Max Cash update (RuneLite 1.13.1 removed the old
	// varbit and does not name this varp). Checked on a live client on 30 Sep 2026: it holds the typed price exactly,
	// including 12,877,762,346. Use the VarPlayerID constant once RuneLite names it.
	private static final int VARP_PRICE = 5753;
	private static final int VARBIT_SELECTED_SLOT = 4439;  // 1-8 while looking at an existing offer, 0 otherwise

	private static final Color GOLD = new Color(0xE0B64B);
	private static final Color GOOD = new Color(0x4CAF7D);
	private static final Color BAD = new Color(0xFF6B6B);

	private final Client client;
	private final ToolkitPanelPlugin plugin;
	private final ToolkitPanelConfig config;
	private final PriceChartComponent chart = new PriceChartComponent();

	@Inject
	GeHelperOverlay(Client client, ToolkitPanelPlugin plugin, ToolkitPanelConfig config)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(230, 0));
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.geOverlay())
		{
			return null;
		}
		Widget ge = client.getWidget(GE_GROUP, 0);
		if (ge == null || ge.isHidden())
		{
			return null;
		}
		// 1) setting up a new offer
		int itemId = client.getVarpValue(VARP_GE_ITEM);
		boolean buy = varbit(VARBIT_TYPE) != 1;   // 0 = buy, 1 = sell; unknown counts as buy
		// A NEW offer's price: -1 when this client can't give it (no such varp), so no price warning is made from it.
		long price = typedPrice();
		boolean existingOffer = false;
		long qty = varbit(VARBIT_QUANTITY);
		// 2) looking at an offer already placed ("Offer status")
		int slot = varbit(VARBIT_SELECTED_SLOT);
		if (itemId <= 0 && slot >= 1 && slot <= 8)
		{
			GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
			GrandExchangeOffer o = offers != null && offers.length >= slot ? offers[slot - 1] : null;
			if (o != null && o.getItemId() > 0 && o.getState() != GrandExchangeOfferState.EMPTY)
			{
				itemId = o.getItemId();
				GrandExchangeOfferState st = o.getState();
				buy = st == GrandExchangeOfferState.BUYING || st == GrandExchangeOfferState.BOUGHT
					|| st == GrandExchangeOfferState.CANCELLED_BUY;
				// getPrice() is a long since RuneLite 1.13.0: an offer can be above 2,147,483,647 gp (Beyond Max Cash)
				price = o.getPrice();
				existingOffer = true;
				qty = Math.max(1L, (long) o.getTotalQuantity() - o.getQuantitySold());
			}
		}
		if (itemId <= 0)
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder().text(Text.t("ge_title")).color(GOLD).build());
		WikiPrices.Price p = plugin.getWikiPrices().get(itemId);
		if (p == null)
		{
			line(Text.t("ge_loading"), "", Color.LIGHT_GRAY);
			return super.render(g);
		}
		boolean priceReadable = existingOffer || price >= 0;
		if (!priceReadable)
		{
			price = 0;   // no warning is made from a price that can't be trusted
		}
		// The last REAL trades: what a seller just accepted (= what the top buyers pay) and what a buyer just paid.
		line(Text.t("ge_last_sell"), Text.t("ge_ago", Text.gp(p.instantSell), Text.ago(p.sellTime)), Color.WHITE);
		line(Text.t("ge_last_buy"), Text.t("ge_ago", Text.gp(p.instantBuy), Text.ago(p.buyTime)), Color.WHITE);
		if (p.avgBuy1h != null || p.avgSell1h != null)
		{
			line(Text.t("ge_avg1h"), Text.gp(p.avgSell1h) + " / " + Text.gp(p.avgBuy1h), Color.LIGHT_GRAY);
		}
		if (p.limit != null)
		{
			line(Text.t("ge_limit"), Text.gp(p.limit) + " / 4h", Color.LIGHT_GRAY);
		}
		if (p.volume1h != null)
		{
			line(Text.t("ge_vol"), Text.gp(p.volume1h), Color.LIGHT_GRAY);
		}
		Long oldest = p.sellTime == null || p.buyTime == null ? null : Math.min(p.sellTime, p.buyTime);
		if (oldest != null && System.currentTimeMillis() / 1000 - oldest > 15 * 60)
		{
			warn(Text.t("ge_stale", Text.ago(oldest)), GOLD);
		}

		if (p.instantBuy != null && p.instantSell != null)
		{
			long low = p.instantSell, high = p.instantBuy;
			if (buy)
			{
				// Resale price, prudent: never above the last instant buy nor the 1h average of instant buys.
				long resale = p.avgBuy1h != null ? Math.min(high, p.avgBuy1h) : high;
				long net = WikiPrices.netSell(resale);
				long maxBid = (long) Math.floor(net / (1 + config.minMarginPct() / 100.0));
				long bid = low + WikiPrices.step(low);   // just above the last accepted price: first in line
				if (bid <= maxBid)
				{
					line(Text.t("ge_bid"), Text.gp(bid) + "  (+" + Text.gp(net - bid) + "/u)", GOOD);
					line(Text.t("ge_bid_max"), Text.gp(maxBid), GOOD);
				}
				else
				{
					warn(Text.t("ge_no_margin"), BAD);
					if (maxBid > 0)
					{
						line(Text.t("ge_bid_max"), Text.gp(maxBid), BAD);
					}
				}
				if (price > 0)
				{
					if (price > high)
					{
						warn(Text.t("ge_warn_over", Text.gp(WikiPrices.saturatingMultiply(price - high, Math.max(qty, 1L)))), BAD);
					}
					else if (price > maxBid)
					{
						warn(Text.t("ge_over_max"), BAD);
					}
					else if (price < bid && bid <= maxBid)
					{
						// Behind the queue while there is still margin: this is where bidding higher pays.
						warn(Text.t("ge_bid_room", Text.gp(maxBid - price)), GOLD);
					}
				}
			}
			else
			{
				long ask = Math.max(low + 1, high - WikiPrices.step(high));   // just under the last instant buy
				line(Text.t("ge_ask"), Text.gp(ask) + "  (" + Text.gp(WikiPrices.netSell(ask)) + " net)", GOOD);
				if (price > 0 && price < low)
				{
					warn(Text.t("ge_warn_under", Text.gp(WikiPrices.saturatingMultiply(low - price, Math.max(qty, 1L)))), BAD);
				}
				else if (price > high)
				{
					warn(Text.t("ge_ask_high"), GOLD);
				}
			}
		}

		if (!priceReadable)
		{
			warn(Text.t("ge_price_unreadable"), GOLD);
		}

		if (config.geChart())
		{
			ChartRange range = config.chartRange();
			chart.range = range;
			chart.points = plugin.getPriceHistory().get(itemId, range);
			chart.lastBuy = p.instantBuy;
			chart.lastSell = p.instantSell;
			chart.offer = price > 0 ? price : null;
			chart.buying = buy;
			chart.alchFloor = p.highAlch != null && p.natureRune != null && p.highAlch - p.natureRune > 0
				? (long) (p.highAlch - p.natureRune) : null;
			panelComponent.getChildren().add(chart);
		}

		final int shownId = itemId;
		ToolkitSnapshot s = plugin.getSnapshot();
		if (s != null && s.flips.stream().anyMatch(r -> r.id == shownId))
		{
			panelComponent.getChildren().add(TitleComponent.builder().text("★ " + Text.t("ge_flip")).color(GOOD).build());
		}
		return super.render(g);
	}

	/** The price typed into a new offer (64-bit), or -1 when the client can't give it. Never throws. */
	private long typedPrice()
	{
		try
		{
			return client.getVarpLongValue(VARP_PRICE);
		}
		catch (RuntimeException e)
		{
			return -1;
		}
	}

	/** A varbit's value, or -1 when the game no longer has it (RuneLite throws "Varbit N does not exist"). Never throws. */
	private int varbit(int id)
	{
		try
		{
			return client.getVarbitValue(id);
		}
		catch (IndexOutOfBoundsException e)
		{
			return -1;
		}
	}

	private void line(String left, String right, Color rightColor)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(left).right(right).rightColor(rightColor).build());
	}

	private void warn(String text, Color color)
	{
		panelComponent.getChildren().add(TitleComponent.builder().text("⚠ " + text).color(color).build());
	}
}

package com.gorsok.toolkitpanel;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.geom.Path2D;
import java.util.List;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * Price chart + "where is the price in its range" gauge, drawn inside the GE helper panel.
 * Band = spread between the average instant-sell (bottom) and instant-buy (top) prices of each step.
 */
class PriceChartComponent implements LayoutableRenderableEntity
{
	private static final int CHART_H = 96, GAUGE_H = 34, GAP = 6;
	private static final Color GRID = new Color(255, 255, 255, 28);
	private static final Color BAND = new Color(224, 182, 75, 60);
	private static final Color LINE = new Color(224, 182, 75);
	private static final Color AVG = new Color(190, 190, 190);
	private static final Color OFFER = new Color(96, 200, 255);
	private static final Color FLOOR = new Color(190, 120, 255);
	private static final Color LAST_BUY = new Color(255, 140, 90);
	private static final Color LAST_SELL = new Color(110, 220, 140);
	private static final Color LOW_ZONE = new Color(76, 175, 125);
	private static final Color MID_ZONE = new Color(140, 140, 140);
	private static final Color HIGH_ZONE = new Color(224, 97, 107);
	private static final Stroke DASH = new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f, new float[]{3f, 3f}, 0f);

	// inputs, set before each render
	List<PriceHistory.Point> points;
	ChartRange range;
	Long lastBuy, lastSell;
	Long offer;          // player's price, or null
	Long alchFloor;         // high alch value - nature rune, or null
	boolean buying;

	private final Point location = new Point();
	private int width = 200;
	private final Rectangle bounds = new Rectangle();

	@Override
	public Dimension render(Graphics2D g)
	{
		int x0 = location.x, y0 = location.y, w = width;
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();

		if (points == null || points.size() < 2)
		{
			g.setColor(Color.LIGHT_GRAY);
			g.drawString(Text.t(points == null ? "chart_loading" : "chart_nodata"), x0, y0 + fm.getAscent());
			int h = fm.getHeight() + 2;
			bounds.setBounds(x0, y0, w, h);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
			return new Dimension(w, h);
		}

		// ---------- scale
		// Robust scale: ignore the 3 % most extreme prices (one troll trade at 20 gp would flatten everything).
		java.util.List<Long> all = new java.util.ArrayList<>();
		for (PriceHistory.Point p : points)
		{
			if (p.high != null) all.add(p.high);
			if (p.low != null) all.add(p.low);
		}
		java.util.Collections.sort(all);
		double lo = PriceHistory.percentile(all, 3), hi = PriceHistory.percentile(all, 97);
		for (Long v : new Long[]{lastBuy, lastSell})
		{
			if (v != null) { lo = Math.min(lo, v); hi = Math.max(hi, v); }
		}
		double dataLo = lo, dataHi = hi;
		// markers stretch the scale only when close to the data, so one silly offer doesn't flatten the chart
		double span0 = Math.max(1, hi - lo);
		for (Number v : new Number[]{offer, alchFloor})
		{
			if (v != null && v.doubleValue() > dataLo - span0 * 0.6 && v.doubleValue() < dataHi + span0 * 0.6)
			{
				lo = Math.min(lo, v.doubleValue());
				hi = Math.max(hi, v.doubleValue());
			}
		}
		double pad = Math.max(1, (hi - lo) * 0.08);
		final double yLo = lo - pad, yHi = hi + pad;

		String topLabel = Text.gp((long) Math.round(dataHi)), botLabel = Text.gp((long) Math.round(dataLo));
		int labelW = Math.max(fm.stringWidth(topLabel), fm.stringWidth(botLabel)) + 4;
		final int cx = x0 + labelW, cw = w - labelW - 4, cy = y0 + 2, ch = CHART_H;
		long t0 = points.get(0).ts, t1 = Math.max(t0 + 1, System.currentTimeMillis() / 1000);

		// ---------- frame + labels
		g.setColor(new Color(0, 0, 0, 70));
		g.fillRect(cx, cy, cw, ch);
		g.setColor(GRID);
		g.drawRect(cx, cy, cw, ch);
		g.drawLine(cx, cy + ch / 2, cx + cw, cy + ch / 2);
		g.setColor(Color.LIGHT_GRAY);
		g.drawString(topLabel, x0, py(dataHi, yLo, yHi, cy, ch) + fm.getAscent() / 2);
		g.drawString(botLabel, x0, py(dataLo, yLo, yHi, cy, ch) + fm.getAscent() / 2);
		String left = "-" + range.label(), right = Text.t("chart_now");
		int ly = cy + ch + fm.getAscent() + 1;
		g.drawString(left, cx, ly);
		g.drawString(right, cx + cw - fm.stringWidth(right), ly);

		// ---------- band + mid line
		Path2D.Double top = new Path2D.Double(), mid = new Path2D.Double();
		Polygon band = new Polygon();
		int[] bottomX = new int[points.size()], bottomY = new int[points.size()];
		int nb = 0;
		boolean started = false;
		for (PriceHistory.Point p : points)
		{
			int px = cx + (int) Math.round((p.ts - t0) * (double) cw / (t1 - t0));
			if (p.high != null && p.low != null)
			{
				band.addPoint(px, py(p.high, yLo, yHi, cy, ch));
				bottomX[nb] = px;
				bottomY[nb++] = py(p.low, yLo, yHi, cy, ch);
			}
			Double m = p.mid();
			if (m != null)
			{
				double yy = py(m, yLo, yHi, cy, ch);
				if (!started) { mid.moveTo(px, yy); started = true; } else { mid.lineTo(px, yy); }
			}
		}
		for (int i = nb - 1; i >= 0; i--)
		{
			band.addPoint(bottomX[i], bottomY[i]);
		}
		java.awt.Shape oldClip = g.getClip();
		g.clipRect(cx, cy, cw + 1, ch + 1);
		g.setColor(BAND);
		g.fillPolygon(band);
		g.setColor(LINE);
		g.setStroke(new BasicStroke(1.4f));
		g.draw(mid);

		// ---------- reference lines
		Double avg = PriceHistory.average(points);
		Stroke old = new BasicStroke(1f);
		g.setStroke(DASH);
		if (avg != null)
		{
			hline(g, avg, AVG, Text.t("chart_avg"), yLo, yHi, cx, cw, cy, ch, fm);
		}
		if (alchFloor != null && alchFloor > 0)
		{
			hline(g, alchFloor, FLOOR, "alch", yLo, yHi, cx, cw, cy, ch, fm);
		}
		if (offer != null && offer > 0)
		{
			hline(g, offer, OFFER, Text.t("chart_you"), yLo, yHi, cx, cw, cy, ch, fm);
		}
		g.setStroke(old);

		// ---------- last real trades at the right edge
		dot(g, lastBuy, LAST_BUY, yLo, yHi, cx + cw - 3, cy, ch);
		dot(g, lastSell, LAST_SELL, yLo, yHi, cx + cw - 3, cy, ch);
		g.setClip(oldClip);

		// ---------- gauge
		int gy = ly + GAP;
		Double pos = null;
		if (lastBuy != null && lastSell != null)
		{
			pos = PriceHistory.position(points, ((double) lastBuy + lastSell) / 2.0);   // not an int sum: 2 x 1.5B would wrap around
		}
		int gh = drawGauge(g, pos, x0, gy, w, fm);

		int h = gy + gh - y0;
		bounds.setBounds(x0, y0, w, h);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		return new Dimension(w, h);
	}

	private int drawGauge(Graphics2D g, Double pos, int x, int y, int w, FontMetrics fm)
	{
		int barY = y + fm.getHeight() + 2, barH = 7;
		String verdict;
		Color vc;
		if (pos == null)
		{
			verdict = Text.t("gauge_unknown");
			vc = Color.LIGHT_GRAY;
		}
		else
		{
			String zone = pos < 1 / 3.0 ? "gauge_low" : pos > 2 / 3.0 ? "gauge_high" : "gauge_mid";
			vc = pos < 1 / 3.0 ? LOW_ZONE : pos > 2 / 3.0 ? HIGH_ZONE : Color.LIGHT_GRAY;
			String hint = "";
			if (buying && pos > 2 / 3.0)
			{
				hint = " · " + Text.t("gauge_hint_buy_high");
			}
			else if (!buying && pos < 1 / 3.0)
			{
				hint = " · " + Text.t("gauge_hint_sell_low");
			}
			verdict = Text.t("gauge_title", Text.t(zone), Math.round(pos * 100), range.label()) + hint;
		}
		g.setColor(vc);
		g.drawString(verdict, x, y + fm.getAscent());

		int third = w / 3;
		g.setColor(alpha(LOW_ZONE, 150));
		g.fillRect(x, barY, third, barH);
		g.setColor(alpha(MID_ZONE, 150));
		g.fillRect(x + third, barY, third, barH);
		g.setColor(alpha(HIGH_ZONE, 150));
		g.fillRect(x + 2 * third, barY, w - 2 * third, barH);
		if (pos != null)
		{
			int mx = x + (int) Math.round(pos * (w - 1));
			g.setColor(Color.WHITE);
			g.fillPolygon(new int[]{mx - 4, mx + 4, mx}, new int[]{barY - 4, barY - 4, barY + 1}, 3);
			g.fillRect(mx - 1, barY, 2, barH);
		}
		g.setColor(Color.GRAY);
		int ly = barY + barH + fm.getAscent() + 1;
		String a = Text.t("gauge_low"), b = Text.t("gauge_mid"), c = Text.t("gauge_high");
		g.drawString(a, x, ly);
		g.drawString(b, x + (w - fm.stringWidth(b)) / 2, ly);
		g.drawString(c, x + w - fm.stringWidth(c), ly);
		return ly - y + 2;
	}

	private static void hline(Graphics2D g, double v, Color c, String label, double yLo, double yHi,
		int cx, int cw, int cy, int ch, FontMetrics fm)
	{
		int y = py(v, yLo, yHi, cy, ch);
		boolean above = y < cy, below = y > cy + ch;
		y = Math.max(cy + 1, Math.min(cy + ch - 1, y));
		g.setColor(c);
		g.drawLine(cx, y, cx + cw, y);
		String s = label + (above ? " ↑" : below ? " ↓" : "");
		int tw = fm.stringWidth(s);
		int ty = y - 2 < cy + fm.getAscent() ? y + fm.getAscent() + 1 : y - 2;
		g.setColor(new Color(0, 0, 0, 150));
		g.fillRect(cx + 2, ty - fm.getAscent() + 1, tw + 2, fm.getAscent());
		g.setColor(c);
		g.drawString(s, cx + 3, ty);
	}

	private static void dot(Graphics2D g, Long v, Color c, double yLo, double yHi, int x, int cy, int ch)
	{
		if (v == null)
		{
			return;
		}
		int y = Math.max(cy + 2, Math.min(cy + ch - 2, py(v, yLo, yHi, cy, ch)));
		g.setColor(Color.BLACK);
		g.fillOval(x - 4, y - 4, 8, 8);
		g.setColor(c);
		g.fillOval(x - 3, y - 3, 6, 6);
	}

	private static int py(double v, double yLo, double yHi, int cy, int ch)
	{
		return cy + (int) Math.round((yHi - v) / (yHi - yLo) * ch);
	}

	private static Color alpha(Color c, int a)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), a);
	}

	@Override
	public Rectangle getBounds()
	{
		return bounds;
	}

	@Override
	public void setPreferredLocation(Point p)
	{
		location.setLocation(p);
	}

	@Override
	public void setPreferredSize(Dimension d)
	{
		if (d != null && d.width > 0)
		{
			width = d.width;
		}
	}
}

package com.gorsok.toolkitpanel;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Price history for the GE chart (OSRS Wiki /timeseries). Fetched on demand, cached 5 minutes per item and range.
 * Prices are {@code Long}: they can be above 2,147,483,647 gp, so no sum or average may be done on 32-bit numbers.
 */
@Slf4j
class PriceHistory
{
	static class Point
	{
		final long ts;
		final Long high, low;   // average instant-buy / instant-sell price in that step (may be null)

		Point(long ts, Long high, Long low)
		{
			this.ts = ts;
			this.high = high;
			this.low = low;
		}

		Double mid()
		{
			if (high != null && low != null)
			{
				return ((double) high + low) / 2.0;   // never an int addition: two 1.5B prices would wrap around
			}
			if (high != null)
			{
				return (double) high;
			}
			if (low != null)
			{
				return (double) low;
			}
			return null;   // a step without any trade (written out: a nested ?: would unbox this null and throw)
		}
	}

	private static final String API = "https://prices.runescape.wiki/api/v1/osrs/timeseries";
	private static final long TTL_MS = 5 * 60_000L;

	private static class Entry
	{
		volatile List<Point> points;
		volatile long fetchedAt;
		volatile boolean loading;
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final Map<String, Entry> cache = new ConcurrentHashMap<>();

	PriceHistory(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	/** Non-blocking: cached points for the range (oldest first), or null while the first download runs. */
	List<Point> get(int itemId, ChartRange range)
	{
		String key = itemId + ":" + range.timestep;
		Entry e = cache.computeIfAbsent(key, k -> new Entry());
		long now = System.currentTimeMillis();
		if (!e.loading && now - e.fetchedAt > TTL_MS)
		{
			e.loading = true;
			download(itemId, range, pts ->
			{
				if (pts != null)
				{
					e.points = pts;
				}
				e.fetchedAt = System.currentTimeMillis();   // also after a failure: retry in 5 min, not every frame
				e.loading = false;
			});
		}
		List<Point> pts = e.points;
		if (pts == null)
		{
			return null;
		}
		long from = now / 1000 - range.seconds;
		List<Point> out = new ArrayList<>();
		for (Point p : pts)
		{
			if (p.ts >= from)
			{
				out.add(p);
			}
		}
		return out;
	}

	private void download(int itemId, ChartRange range, java.util.function.Consumer<List<Point>> done)
	{
		Request req = new Request.Builder().url(API + "?timestep=" + range.timestep + "&id=" + itemId)
			.header("User-Agent", WikiPrices.USER_AGENT).build();
		http.newCall(req).enqueue(new okhttp3.Callback()
		{
			@Override
			public void onFailure(okhttp3.Call call, java.io.IOException ex)
			{
				log.debug("price history {}: {}", itemId, ex.getMessage());
				done.accept(null);
			}

			@Override
			public void onResponse(okhttp3.Call call, Response r)
			{
				List<Point> out = null;
				try (ResponseBody b = r.body())
				{
					if (r.isSuccessful() && b != null)
					{
						JsonObject o = gson.fromJson(b.string(), JsonObject.class);
						JsonArray arr = o.has("data") && o.get("data").isJsonArray() ? o.getAsJsonArray("data") : new JsonArray();
						out = new ArrayList<>(arr.size());
						for (JsonElement el : arr)
						{
							JsonObject p = el.getAsJsonObject();
							out.add(new Point(p.get("timestamp").getAsLong(),
								WikiPrices.num(p, "avgHighPrice"), WikiPrices.num(p, "avgLowPrice")));
						}
					}
				}
				catch (java.io.IOException | RuntimeException ex)
				{
					log.debug("price history {}: {}", itemId, ex.getMessage());
				}
				done.accept(out);
			}
		});
	}

	/** Where the current price sits in the range's usual prices (5th-95th percentile): 0 = bottom, 1 = top. */
	static Double position(List<Point> pts, double current)
	{
		List<Long> mids = new ArrayList<>();
		for (Point p : pts)
		{
			Double m = p.mid();
			if (m != null)
			{
				mids.add(Math.round(m));
			}
		}
		if (mids.size() < 5)
		{
			return null;
		}
		Collections.sort(mids);
		double lo = percentile(mids, 5), hi = percentile(mids, 95);
		if (hi - lo < 1e-9)
		{
			return null;
		}
		return Math.max(0, Math.min(1, (current - lo) / (hi - lo)));
	}

	/** Percentile of an already sorted list. */
	static double percentile(List<Long> sorted, double pct)
	{
		if (sorted.isEmpty())
		{
			return 0;
		}
		double k = (sorted.size() - 1) * pct / 100.0;
		int f = (int) Math.floor(k), c = Math.min(sorted.size() - 1, f + 1);
		double a = sorted.get(f), b = sorted.get(c);
		return a + (b - a) * (k - f);
	}

	static Double average(List<Point> pts)
	{
		double sum = 0;
		int n = 0;
		for (Point p : pts)
		{
			Double m = p.mid();
			if (m != null)
			{
				sum += m;
				n++;
			}
		}
		return n == 0 ? null : sum / n;
	}
}

