	}

	private static void put(String k, String en, String fr)
	{
		T.put(k, new String[]{en, fr});
	}

	static boolean fr = false;

	static String t(String key, Object... args)
	{
		String[] v = T.get(key);
		String s = v == null ? key : v[fr ? 1 : 0];
		return args.length == 0 ? s : String.format(s, args);
	}

	/** 1234567 -> "1.23M", 12345 -> "12.3k", 950 -> "950". */
	static String gp(Long n)
	{
		if (n == null)
		{
			return "?";
		}
		long a = Math.abs(n);
		String s;
		if (a >= 1_000_000_000_000L)
		{
			s = trim(n / 1e12) + "T";
		}
		else if (a >= 1_000_000_000L)
		{
			s = trim(n / 1e9) + "B";
		}
		else if (a >= 1_000_000L)
		{
			s = trim(n / 1e6) + "M";
		}
		else if (a >= 10_000L)
		{
			s = trim(n / 1e3) + "k";
		}
		else
		{
			s = NumberFormat.getIntegerInstance(Locale.US).format(n);
			if (fr)
			{
				s = s.replace(',', ' ');   // plain space: the RuneScape font has no narrow no-break space
			}
		}
		return s;
	}

	static String gp(Integer n)
	{
		return n == null ? "?" : gp((long) n);
	}

	private static String trim(double v)
	{
		String s = String.format(Locale.US, Math.abs(v) >= 100 ? "%.0f" : Math.abs(v) >= 10 ? "%.1f" : "%.2f", v);
		if (s.contains("."))
		{
			s = s.replaceAll("0+$", "").replaceAll("\\.$", "");
		}
		return fr ? s.replace('.', ',') : s;
	}

	/** 75 -> "1m", 5000 -> "1h23m", 30 -> "30s". */
	static String ago(Long unixSeconds)
	{
		if (unixSeconds == null)
		{
			return "?";
		}
		long s = Math.max(0, System.currentTimeMillis() / 1000 - unixSeconds);
		if (s < 60)
		{
			return s + "s";
		}
		if (s < 3600)
		{
			return (s / 60) + "m";
		}
		return (s / 3600) + "h" + String.format("%02d", (s % 3600) / 60);
	}

	static String pct(Double d)
	{
		if (d == null)
		{
			return "?";
		}
		String s = String.format(Locale.US, "%.1f", d);
		return fr ? s.replace('.', ',') : s;
	}

	private Text()
	{
	}
}

package com.gorsok.toolkitpanel;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Reads the OSRS Toolkit companion app running on this computer (http://127.0.0.1:&lt;port&gt;).
 * GET requests only, all asynchronous (OkHttp enqueue): never blocks the client thread or RuneLite's executor.
 */
@Slf4j
class ToolkitClient
{
	private final OkHttpClient http;
	private final Gson gson;
	private volatile int port = 8765;

	ToolkitClient(OkHttpClient base, Gson gson)
	{
		this.http = base.newBuilder()
			.connectTimeout(1, TimeUnit.SECONDS)
			.readTimeout(4, TimeUnit.SECONDS)
			.proxy(java.net.Proxy.NO_PROXY)   // it's on this computer: never go through a system proxy
			.build();
		this.gson = gson;
	}

	String dashboardUrl()
	{
		return "http://127.0.0.1:" + port + "/";
	}

	/** Calls {@code done} (on an OkHttp thread) with a snapshot; connected=false when the app isn't running. */
	void fetch(int configuredPort, Consumer<ToolkitSnapshot> done)
	{
		// 0 or an invalid value (e.g. saved by an older version where 0 meant "automatic") -> default port
		port = configuredPort > 0 && configuredPort <= 65535 ? configuredPort : 8765;
		final int usedPort = port;
		ToolkitSnapshot s = new ToolkitSnapshot();
		get("/api/ping", ping ->
		{
			JsonObject p = json(ping);
			if (p == null || !"osrs-ge-toolkit".equals(str(p, "app")))
			{
				done.accept(s);   // not running (or something else on that port)
				return;
			}
			s.connected = true;
			s.port = usedPort;
			s.version = str(p, "version");

			AtomicInteger remaining = new AtomicInteger(3);
			Runnable finish = () ->
			{
				if (remaining.decrementAndGet() == 0)
				{
					done.accept(s);
				}
			};
			get("/api/stream/state", body ->
			{
				JsonObject st = json(body);
				if (st != null && st.has("bond") && st.get("bond").isJsonObject())
				{
					JsonObject b = st.getAsJsonObject("bond");
					synchronized (s)
					{
						s.character = str(b, "character");
						s.bondPrice = lng(b, "price");
						s.cash = lng(b, "cash");
						s.bondPct = dbl(b, "pct");
					}
				}
				finish.run();
			});
			get("/data/market.json", body ->
			{
				JsonObject m = json(body);
				if (m != null)
				{
					synchronized (s)
					{
						s.scanTime = str(m, "generated_at");
						s.flips = rows(m, "flips_best_gp_per_hour", 8);
						s.alchs = rows(m, "alch", 4);
					}
				}
				finish.run();
			});
			get("/data/alerts.jsonl", body ->
			{
				List<ToolkitSnapshot.Alert> alerts = parseAlerts(body);
				synchronized (s)
				{
					s.alerts = alerts;
				}
				finish.run();
			});
		});
	}

	/** Async GET; {@code onBody} receives the body, or null on any error / 404. */
	private void get(String path, Consumer<String> onBody)
	{
		Request req = new Request.Builder().url("http://127.0.0.1:" + port + path).build();
		http.newCall(req).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Toolkit {}: {}", path, e.getMessage());
				onBody.accept(null);
			}

			@Override
			public void onResponse(Call call, Response r)
			{
				String body = null;
				try (ResponseBody b = r.body())
				{
					if (r.isSuccessful() && b != null)
					{
						body = b.string();
					}
				}
				catch (IOException e)
				{
					log.debug("Toolkit {}: {}", path, e.getMessage());
				}
				onBody.accept(body);
			}
		});
	}

	private List<ToolkitSnapshot.Alert> parseAlerts(String text)
	{
		List<ToolkitSnapshot.Alert> out = new ArrayList<>();
		if (text == null)
		{
			return out;
		}
		String[] lines = text.split("\n");
		for (int i = lines.length - 1; i >= 0 && out.size() < 25; i--)
		{
			String line = lines[i].trim();
			if (line.isEmpty())
			{
				continue;
			}
			try
			{
				JsonObject a = gson.fromJson(line, JsonObject.class);
				ToolkitSnapshot.Alert al = new ToolkitSnapshot.Alert();
				al.ts = str(a, "ts");
				al.category = str(a, "category");
				al.title = str(a, "title");
				al.body = str(a, "body");
				al.important = a.has("important") && a.get("important").isJsonPrimitive() && a.get("important").getAsBoolean();
				out.add(al);   // newest first
			}
			catch (RuntimeException ignored)
			{
				// half-written line: skip it
			}
		}
		return out;
	}

	private JsonObject json(String t)
	{
		if (t == null)
		{
			return null;
		}
		try
		{
			JsonElement e = gson.fromJson(t, JsonElement.class);
			return e != null && e.isJsonObject() ? e.getAsJsonObject() : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static List<ToolkitSnapshot.Row> rows(JsonObject m, String key, int max)
	{
		List<ToolkitSnapshot.Row> out = new ArrayList<>();
		if (!m.has(key) || !m.get(key).isJsonArray())
		{
			return out;
		}
		JsonArray arr = m.getAsJsonArray(key);
		for (int i = 0; i < arr.size() && out.size() < max; i++)
		{
			if (!arr.get(i).isJsonObject())
			{
				continue;
			}
			JsonObject o = arr.get(i).getAsJsonObject();
			ToolkitSnapshot.Row r = new ToolkitSnapshot.Row();
			Long id = lng(o, "id");
			r.id = id == null ? 0 : id.intValue();
			r.name = str(o, "name");
			r.buy = lng(o, "buy_at");
			r.sell = lng(o, "sell_at");
			r.margin = lng(o, "net_margin");
			r.roi = dbl(o, "roi_pct");
			r.gpPerHour = lng(o, "gp_per_hour");
			r.qty = lng(o, "qty_per_cycle");
			r.alchValue = lng(o, "alch_value");
			r.profitPerCast = lng(o, "profit_per_cast");
			r.volatile_ = o.has("volatile") && o.get("volatile").isJsonPrimitive() && o.get("volatile").getAsBoolean();
			out.add(r);
		}
		return out;
	}

	static String str(JsonObject o, String k)
	{
		return o.has(k) && o.get(k).isJsonPrimitive() ? o.get(k).getAsString() : null;
	}

	static Long lng(JsonObject o, String k)
	{
		try
		{
			return o.has(k) && o.get(k).isJsonPrimitive() ? o.get(k).getAsLong() : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	static Double dbl(JsonObject o, String k)
	{
		try
		{
			return o.has(k) && o.get(k).isJsonPrimitive() ? o.get(k).getAsDouble() : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.gorsok.toolkitpanel;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JProgressBar;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

/** Side panel. Call {@link #update} on the Swing thread only. */
class ToolkitPanel extends PluginPanel
{
	private static final Color GOLD = new Color(0xE0B64B);
	private static final Color GOOD = new Color(0x4CAF7D);
	private static final Color BAD = new Color(0xE0616B);
	private static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR.darker();

	private final JPanel content = new JPanel();
	private final Supplier<String> dashboardUrl;

	ToolkitPanel(Supplier<String> dashboardUrl)
	{
		super(false);
		this.dashboardUrl = dashboardUrl;
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(new EmptyBorder(10, 10, 10, 10));
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JPanel north = new WidthTrackingPanel();
		north.setBackground(ColorScheme.DARK_GRAY_COLOR);
		north.add(content, BorderLayout.NORTH);
		javax.swing.JScrollPane scroll = new javax.swing.JScrollPane(north);
		scroll.setBorder(null);
		scroll.setHorizontalScrollBarPolicy(javax.swing.ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll, BorderLayout.CENTER);
		showSnapshot(null);
	}

	void showSnapshot(ToolkitSnapshot s)
	{
		content.removeAll();

		JLabel title = new JLabel("OSRS Toolkit");
		title.setFont(FontManager.getRunescapeBoldFont().deriveFont(Font.BOLD, 20f));
		title.setForeground(GOLD);
		put(title, 0);

		if (s == null || !s.connected)
		{
			put(label(Text.t("offline"), BAD, true), 4);
			put(wrap(Text.t("offline_hint"), MUTED), 8);
			JButton get = new JButton(Text.t("get_toolkit"));
			get.setFocusable(false);
			get.addActionListener(e -> LinkBrowser.browse("https://github.com/Gorsokk/osrs-toolkit"));
			put(get, 10);
			content.revalidate();
			content.repaint();
			return;
		}

		String who = s.character != null ? " · " + s.character : "";
		put(label(Text.t("connected", s.version != null ? s.version : "") + who, GOOD, false), 2);

		// --- bond
		put(header(Text.t("bond")), 12);
		JPanel bond = card();
		if (s.bondPct != null && s.bondPrice != null)
		{
			JProgressBar bar = new JProgressBar(0, 1000);
			bar.setValue((int) Math.round(s.bondPct * 10));
			bar.setStringPainted(true);
			bar.setString(Text.pct(s.bondPct) + " %");
			bar.setForeground(GOLD);
			bar.setBackground(ColorScheme.DARKER_GRAY_COLOR.darker());
			bar.setAlignmentX(Component.LEFT_ALIGNMENT);
			bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
			bond.add(bar);
			bond.add(Box.createVerticalStrut(4));
			bond.add(label(Text.t("bond_line", Text.gp(s.cash), Text.gp(s.bondPrice)), ColorScheme.LIGHT_GRAY_COLOR, false));
		}
		else
		{
			bond.add(label(Text.t("bond_none"), MUTED, false));
		}
		put(bond, 4);

		// --- flips
		put(header(Text.t("flips")), 12);
		if (s.flips.isEmpty())
		{
			put(wrap(Text.t("no_scan"), MUTED), 4);
		}
		for (ToolkitSnapshot.Row r : s.flips)
		{
			JPanel c = card();
			c.add(label(r.name + (r.volatile_ ? "  ⚠ " + Text.t("volatile") : ""), r.volatile_ ? GOLD : Color.WHITE, true));
			c.add(label(Text.t("flip_line", Text.gp(r.buy), Text.gp(r.sell), Text.pct(r.roi), Text.gp(r.gpPerHour)),
				ColorScheme.LIGHT_GRAY_COLOR, false));
			put(c, 3);
		}

		// --- alch
		if (!s.alchs.isEmpty())
		{
			put(header(Text.t("alchs")), 12);
			for (ToolkitSnapshot.Row r : s.alchs)
			{
				JPanel c = card();
				c.add(label(r.name, Color.WHITE, true));
				c.add(label(Text.t("alch_line", Text.gp(r.buy), Text.gp(r.profitPerCast)), ColorScheme.LIGHT_GRAY_COLOR, false));
				put(c, 3);
			}
		}
		if (s.scanTime != null)
		{
			put(label(Text.t("scan", s.scanTime.replace('T', ' ').replaceAll("[-+]\\d{4}$", "")), MUTED, false), 4);
		}

		// --- alerts
		put(header(Text.t("alerts")), 12);
		if (s.alerts.isEmpty())
		{
			put(label(Text.t("no_alerts"), MUTED, false), 4);
		}
		int shown = 0;
		for (ToolkitSnapshot.Alert a : s.alerts)
		{
			if (shown++ >= 10)
			{
				break;
			}
			JPanel c = card();
			String time = a.ts != null && a.ts.length() >= 16 ? a.ts.substring(11, 16) : "";
			c.add(label(time + "  " + (a.category != null ? a.category : ""), a.important ? GOLD : MUTED, false));
			c.add(wrap(a.title, a.important ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR));
			if (a.body != null && !a.body.isEmpty())
			{
				c.setToolTipText("<html><body style='width:220px'>" + escape(a.body) + "</body></html>");
			}
			put(c, 3);
		}

		JButton open = new JButton(Text.t("dashboard"));
		open.setAlignmentX(Component.LEFT_ALIGNMENT);
		open.setFocusable(false);
		open.addActionListener(e -> LinkBrowser.browse(dashboardUrl.get()));
		put(open, 14);

		content.revalidate();
		content.repaint();
	}

	// ------------------------------------------------------------------ helpers
	private void put(Component c, int gapBefore)
	{
		if (gapBefore > 0 && content.getComponentCount() > 0)
		{
			content.add(Box.createVerticalStrut(gapBefore));
		}
		if (c instanceof javax.swing.JComponent)
		{
			((javax.swing.JComponent) c).setAlignmentX(Component.LEFT_ALIGNMENT);
		}
		content.add(c);
	}

	private static JLabel header(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(GOLD);
		return l;
	}

	private static JLabel label(String text, Color color, boolean bold)
	{
		JLabel l = new JLabel(text);
		l.setFont(bold ? FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD) : FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	/** Label that wraps to the panel width. */
	private static JLabel wrap(String text, Color color)
	{
		JLabel l = new JLabel("<html><body style='width:" + (PANEL_WIDTH - 70) + "px'>" + escape(text) + "</body></html>");
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private static JPanel card()
	{
		JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(BorderFactory.createEmptyBorder(5, 7, 5, 7));
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
		return p;
	}

	/** Follows the scroll pane's width, so nothing is cut off on the right. */
	private static class WidthTrackingPanel extends JPanel implements javax.swing.Scrollable
	{
		WidthTrackingPanel()
		{
			super(new BorderLayout());
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(java.awt.Rectangle r, int o, int d)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(java.awt.Rectangle r, int o, int d)
		{
			return 64;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	private static String escape(String s)
	{
		return s == null ? "" : s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

