package com.gorsok.toolkitpanel;

// OSRS Toolkit Panel: shows the local OSRS Toolkit app inside RuneLite.
//   - side panel: bond progress, top flips, High Alch picks, recent alerts
//   - infobox: % toward a bond
//   - game chat: new Toolkit alerts (important ones by default)
//   - GE offer window: instant prices, margin after tax, buy limit, warning when the price is off
// The side panel reads the optional OSRS Toolkit app on this computer (http://127.0.0.1:8765, GET only).
// The GE helper uses the OSRS Wiki prices API and is OFF by default (third-party server warning).
// Nothing about your account is ever sent anywhere.

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.ImageUtil;
import okhttp3.OkHttpClient;

@Slf4j
@PluginDescriptor(
	name = "OSRS Toolkit Panel",
	description = "GE price helper with price chart, plus bond progress, top flips and alerts from the OSRS Toolkit app",
	tags = {"grand exchange", "ge", "flipping", "bond", "prices", "toolkit"}
)
public class ToolkitPanelPlugin extends Plugin
{
	private static final int OLD_SCHOOL_BOND = 13190;

	@Inject private ToolkitPanelConfig config;
	@Inject private ClientToolbar clientToolbar;
	@Inject private OverlayManager overlayManager;
	@Inject private InfoBoxManager infoBoxManager;
	@Inject private ItemManager itemManager;
	@Inject private ChatMessageManager chatMessageManager;
	@Inject private ClientThread clientThread;
	@Inject private ScheduledExecutorService executor;
	@Inject private OkHttpClient okHttpClient;
	@Inject private Gson gson;
	@Inject private GeHelperOverlay geOverlay;

	private ToolkitClient toolkit;
	@Getter private WikiPrices wikiPrices;
	@Getter private PriceHistory priceHistory;
	@Getter private volatile ToolkitSnapshot snapshot;

	private ToolkitPanel panel;
	private NavigationButton navButton;
	private BondInfoBox bondBox;
	private ScheduledFuture<?> poller;
	private final Set<String> seenAlerts = new HashSet<>();
	private final java.util.concurrent.atomic.AtomicBoolean polling = new java.util.concurrent.atomic.AtomicBoolean();
	private boolean alertsSeeded;

	@Provides
	ToolkitPanelConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ToolkitPanelConfig.class);
	}

	@Override
	protected void startUp()
	{
		Text.fr = config.language() == ToolkitPanelConfig.Language.FRANCAIS;
		toolkit = new ToolkitClient(okHttpClient, gson);
		wikiPrices = new WikiPrices(okHttpClient, gson);
		priceHistory = new PriceHistory(okHttpClient, gson);
		snapshot = null;
		seenAlerts.clear();
		alertsSeeded = false;
		polling.set(false);

		panel = new ToolkitPanel(toolkit::dashboardUrl);
		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder().tooltip("OSRS Toolkit").icon(icon).priority(7).panel(panel).build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(geOverlay);
		schedule();
	}

	@Override
	protected void shutDown()
	{
		if (poller != null)
		{
			poller.cancel(false);
			poller = null;
		}
		overlayManager.remove(geOverlay);
		clientToolbar.removeNavigation(navButton);
		removeBondBox();
		panel = null;
		snapshot = null;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (!ToolkitPanelConfig.GROUP.equals(e.getGroup()))
		{
			return;
		}
		Text.fr = config.language() == ToolkitPanelConfig.Language.FRANCAIS;
		schedule();   // new interval / port, and redraw right away
	}

	private void schedule()
	{
		if (poller != null)
		{
			poller.cancel(false);
		}
		poller = executor.scheduleWithFixedDelay(this::poll, 0, config.refreshSeconds(), TimeUnit.SECONDS);
	}

	/** RuneLite's executor: only starts the async requests, never waits on the network. */
	private void poll()
	{
		if (!polling.compareAndSet(false, true))
		{
			return;   // previous refresh still running
		}
		toolkit.fetch(config.port(), s ->
		{
			polling.set(false);
			snapshot = s;
			ToolkitPanel p = panel;
			if (p != null)
			{
				SwingUtilities.invokeLater(() -> p.showSnapshot(s));
			}
			clientThread.invokeLater(() -> updateBondBox(s));
			if (s.connected)
			{
				announceAlerts(s.alerts);
			}
		});
	}

	private void updateBondBox(ToolkitSnapshot s)
	{
		boolean want = config.bondInfobox() && s.connected && s.bondPct != null;
		if (!want)
		{
			removeBondBox();
			return;
		}
		if (bondBox == null)
		{
			bondBox = new BondInfoBox(itemManager.getImage(OLD_SCHOOL_BOND), this);
			infoBoxManager.addInfoBox(bondBox);
		}
		bondBox.setSnapshot(s);
	}

	private void removeBondBox()
	{
		if (bondBox != null)
		{
			infoBoxManager.removeInfoBox(bondBox);
			bondBox = null;
		}
	}

	/** Posts alerts that appeared since the last refresh. The first refresh only remembers what already exists. */
	private synchronized void announceAlerts(List<ToolkitSnapshot.Alert> newestFirst)
	{
		if (!alertsSeeded)
		{
			newestFirst.forEach(a -> seenAlerts.add(a.key()));
			alertsSeeded = true;
			return;
		}
		for (int i = newestFirst.size() - 1; i >= 0; i--)
		{
			ToolkitSnapshot.Alert a = newestFirst.get(i);
			if (!seenAlerts.add(a.key()))
			{
				continue;
			}
			if (!config.chatAlerts() || (config.chatImportantOnly() && !a.important) || a.title == null)
			{
				continue;
			}
			String msg = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("[" + Text.t("chat_prefix") + "] ")
				.append(ChatColorType.NORMAL).append(a.title)
				.build();
			chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE).runeLiteFormattedMessage(msg).build());
		}
		if (seenAlerts.size() > 500)
		{
			seenAlerts.clear();
			newestFirst.forEach(a -> seenAlerts.add(a.key()));
		}
	}
}

package com.gorsok.toolkitpanel;

import java.util.ArrayList;
import java.util.List;

/** What the panel shows, as read from the Toolkit. Immutable once handed to the UI. */
class ToolkitSnapshot
{
	boolean connected;
	int port;
	String version;
	String character;

	Long bondPrice;
	Long cash;
	Double bondPct;

	String scanTime;
	List<Row> flips = new ArrayList<>();
	List<Row> alchs = new ArrayList<>();
	List<Alert> alerts = new ArrayList<>();   // newest first

	static class Row
	{
		int id;
		String name;
		Long buy, sell, margin, gpPerHour, qty, alchValue, profitPerCast;
		Double roi;
		boolean volatile_;
	}

	static class Alert
	{
		String ts, category, title, body;
		boolean important;

		String key()
		{
			return ts + "|" + title;
		}
	}
}

package com.gorsok.toolkitpanel;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Prices for the GE helper, from the OSRS Wiki real-time prices API (third-party: only used when the user enables it).
 * Refreshed only while the GE is open, asynchronously; cached (latest 60 s, 1h averages 5 min, item data 24 h).
 *
 * Prices are {@code Long}: since Beyond Max Cash, GE prices can be above 2,147,483,647 gp.
 */
@Slf4j
class WikiPrices
{
	static final String API = "https://prices.runescape.wiki/api/v1/osrs";
	static final String USER_AGENT = "OSRS Toolkit Panel RuneLite plugin - github.com/Gorsokk/osrs-toolkit-panel";
	private static final int NATURE_RUNE = 561;

	static class Price
	{
		Long instantBuy, instantSell;   // last real instant-buy / instant-sell trades ("high" / "low")
		Long buyTime, sellTime;         // when they happened (unix seconds)
		Long avgBuy1h, avgSell1h;
		Long volume1h;
		Integer limit;
		Integer highAlch;
		Integer natureRune;
	}

	private final OkHttpClient http;
	private final Gson gson;

	private volatile JsonObject latest, hour;
	private volatile Map<Integer, Integer> limits = new HashMap<>(), alchs = new HashMap<>();
	private volatile long latestAt, hourAt, mappingAt;
	private final AtomicBoolean latestBusy = new AtomicBoolean(), hourBusy = new AtomicBoolean(), mappingBusy = new AtomicBoolean();

	WikiPrices(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	/** Non-blocking: what is cached (maybe null), and starts a background refresh when stale. */
	Price get(int itemId)
	{
		refreshIfStale();
		JsonObject l = latest, h = hour;
		if (l == null)
		{
			return null;
		}
		Price p = new Price();
		JsonObject li = obj(l, String.valueOf(itemId));
		if (li != null)
		{
			p.instantBuy = num(li, "high");
			p.instantSell = num(li, "low");
			p.buyTime = num(li, "highTime");
			p.sellTime = num(li, "lowTime");
		}
		JsonObject hi = h == null ? null : obj(h, String.valueOf(itemId));
		if (hi != null)
		{
			p.avgBuy1h = num(hi, "avgHighPrice");
			p.avgSell1h = num(hi, "avgLowPrice");
			Long a = num(hi, "highPriceVolume"), b = num(hi, "lowPriceVolume");
			p.volume1h = (a == null ? 0L : a) + (b == null ? 0L : b);
		}
		p.limit = limits.get(itemId);
		p.highAlch = alchs.get(itemId);
		JsonObject nat = obj(l, String.valueOf(NATURE_RUNE));
		p.natureRune = nat == null ? null : intNum(nat, "high");
		return p;
	}

	private void refreshIfStale()
	{
		long now = System.currentTimeMillis();
		if (now - latestAt > 60_000 && latestBusy.compareAndSet(false, true))
		{
			fetch("/latest", raw ->
			{
				JsonObject d = data(raw);
				if (d != null)
				{
					latest = d;
				}
				latestAt = System.currentTimeMillis() - (d == null ? 30_000 : 0);   // failed: retry in ~30 s
				latestBusy.set(false);
			});
		}
		if (now - hourAt > 300_000 && hourBusy.compareAndSet(false, true))
		{
			fetch("/1h", raw ->
			{
				JsonObject d = data(raw);
				if (d != null)
				{
					hour = d;
				}
				hourAt = System.currentTimeMillis() - (d == null ? 270_000 : 0);
				hourBusy.set(false);
			});
		}
		if (now - mappingAt > 86_400_000 && mappingBusy.compareAndSet(false, true))
		{
			fetch("/mapping", raw ->
			{
				boolean ok = false;
				try
				{
					if (raw != null)
					{
						Map<Integer, Integer> lim = new HashMap<>(), ha = new HashMap<>();
						for (JsonElement e : gson.fromJson(raw, JsonArray.class))
						{
							JsonObject o = e.getAsJsonObject();
							Integer id = intNum(o, "id"), l = intNum(o, "limit"), alch = intNum(o, "highalch");
							if (id != null && l != null)
							{
								lim.put(id, l);
							}
							if (id != null && alch != null)
							{
								ha.put(id, alch);
							}
						}
						limits = lim;
						alchs = ha;
						ok = true;
					}
				}
				catch (RuntimeException e)
				{
					log.debug("Wiki mapping: {}", e.getMessage());
				}
				mappingAt = System.currentTimeMillis() - (ok ? 0 : 86_400_000 - 60_000);
				mappingBusy.set(false);
			});
		}
	}

	private void fetch(String path, Consumer<String> onBody)
	{
		Request req = new Request.Builder().url(API + path).header("User-Agent", USER_AGENT).build();
		http.newCall(req).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Wiki prices {}: {}", path, e.getMessage());
				onBody.accept(null);
			}

			@Override
			public void onResponse(Call call, Response r)
			{
				String body = null;
				try (ResponseBody b = r.body())
				{
					if (r.isSuccessful() && b != null)
					{
						body = b.string();
					}
				}
				catch (IOException e)
				{
					log.debug("Wiki prices {}: {}", path, e.getMessage());
				}
				onBody.accept(body);
			}
		});
	}

	private JsonObject data(String raw)
	{
		try
		{
			return raw == null ? null : obj(gson.fromJson(raw, JsonObject.class), "data");
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static JsonObject obj(JsonObject o, String k)
	{
		return o != null && o.has(k) && o.get(k).isJsonObject() ? o.getAsJsonObject(k) : null;
	}

	/** A JSON number as a Long (never narrowed to 32 bits), or null when missing, null or not a number. */
	static Long num(JsonObject o, String k)
	{
		try
		{
			return o != null && o.has(k) && o.get(k).isJsonPrimitive() ? o.get(k).getAsLong() : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/** For small values only (item ids, buy limits, alch values): null instead of a wrapped-around number. */
	static Integer intNum(JsonObject o, String k)
	{
		Long v = num(o, k);
		return v == null || v > Integer.MAX_VALUE || v < Integer.MIN_VALUE ? null : Integer.valueOf(v.intValue());
	}

	/** a * b, stuck at Long.MAX_VALUE / MIN_VALUE instead of wrapping around. */
	static long saturatingMultiply(long a, long b)
	{
		try
		{
			return Math.multiplyExact(a, b);
		}
		catch (ArithmeticException e)
		{
			return (a < 0) == (b < 0) ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	/** Smallest step that still puts you in front of the other offers at this price level. */
	static long step(long price)
	{
		return Math.max(1, Math.round(price * 0.002));
	}

	/** GE tax: 2 % (rounded down), none under 50 gp, capped at 5M. */
	static long netSell(long price)
	{
		if (price < 50)
		{
			return price;
		}
		return price - Math.min((long) (price * 0.02), 5_000_000L);
	}
}

package com.gorsok.toolkitpanel;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

/**
 * Prices above 2,147,483,647 gp (Beyond Max Cash): nothing may wrap around, be clamped or throw.
 * Plain unit tests: no RuneLite client and no network needed.
 */
public class BeyondMaxCashTest
{
	private static final long G = 1_000_000_000L;

	@Before
	public void english()
	{
		Text.fr = false;   // static: don't depend on the order the tests run in
	}

	private static JsonObject json(String s)
	{
		return new Gson().fromJson(s, JsonObject.class);
	}

	private static PriceHistory.Point point(long ts, Long high, Long low)
	{
		return new PriceHistory.Point(ts, high, low);
	}

	// ---------------------------------------------------------------- JSON numbers
	@Test
	public void wikiPricesAboveTheIntRangeAreNotTruncated()
	{
		JsonObject o = json("{\"high\":3500000000,\"low\":null,\"text\":\"abc\"}");
		assertEquals(Long.valueOf(3_500_000_000L), WikiPrices.num(o, "high"));
		assertNull(WikiPrices.num(o, "low"));
		assertNull(WikiPrices.num(o, "text"));
		assertNull(WikiPrices.num(o, "missing"));
		assertNull(WikiPrices.num(null, "high"));
	}

	@Test
	public void smallValuesRefuseToWrapAround()
	{
		JsonObject o = json("{\"id\":13190,\"big\":3500000000}");
		assertEquals(Integer.valueOf(13190), WikiPrices.intNum(o, "id"));
		assertNull("must be null, not a wrapped-around negative number", WikiPrices.intNum(o, "big"));
	}

	// ---------------------------------------------------------------- history points
	@Test
	public void midOfTwoPricesAbove1_07BillionDoesNotOverflow()
	{
		// Integer 1.5B + 1.5B wraps around to a negative number: this was a bug before Beyond Max Cash too.
		assertEquals(1.5 * G, point(0, 1_500_000_000L, 1_500_000_000L).mid().doubleValue(), 0.0001);
		assertEquals(3.45 * G, point(0, 3_500_000_000L, 3_400_000_000L).mid().doubleValue(), 0.0001);
	}

	@Test
	public void midWithOnlyOneSideOrNoTradeAtAll()
	{
		assertEquals(5_000.0, point(0, 5_000L, null).mid().doubleValue(), 0.0001);
		assertEquals(4_000.0, point(0, null, 4_000L).mid().doubleValue(), 0.0001);
		// a 5-minute step without any trade: used to throw a NullPointerException (unboxed null)
		assertNull(point(0, null, null).mid());
	}

	private static List<PriceHistory.Point> sixPointsBetween3And4Billion()
	{
		List<PriceHistory.Point> pts = new ArrayList<>();
		long[] mids = {3_000_000_000L, 3_200_000_000L, 3_400_000_000L, 3_600_000_000L, 3_800_000_000L, 4_000_000_000L};
		for (int i = 0; i < mids.length; i++)
		{
			pts.add(point(i, mids[i], mids[i]));
		}
		return pts;
	}

	@Test
	public void percentileOfValuesAboveTheIntRange()
	{
		List<Long> sorted = Arrays.asList(1L, 3_000_000_000L);
		assertEquals(1.0, PriceHistory.percentile(sorted, 0), 1e-6);
		assertEquals(1_500_000_000.5, PriceHistory.percentile(sorted, 50), 1e-6);
		assertEquals(3.0 * G, PriceHistory.percentile(sorted, 100), 1e-6);
		assertEquals(0.0, PriceHistory.percentile(new ArrayList<Long>(), 50), 0.0);
	}

	@Test
	public void gaugePositionWithPricesAbove2_147Billion()
	{
		// 5th percentile = 3.05B, 95th = 3.95B: 3.5B is exactly in the middle
		assertEquals(0.5, PriceHistory.position(sixPointsBetween3And4Billion(), 3.5 * G), 1e-9);
		assertEquals(0.0, PriceHistory.position(sixPointsBetween3And4Billion(), 1.0 * G), 1e-9);
		assertEquals(1.0, PriceHistory.position(sixPointsBetween3And4Billion(), 9.0 * G), 1e-9);
	}

	@Test
	public void gaugeNeedsEnoughPoints()
	{
		List<PriceHistory.Point> few = sixPointsBetween3And4Billion().subList(0, 4);
		assertNull(PriceHistory.position(few, 3.5 * G));
	}

	@Test
	public void averageOfValuesAboveTheIntRange()
	{
		assertEquals(3.5 * G, PriceHistory.average(sixPointsBetween3And4Billion()), 1e-3);
		assertNull(PriceHistory.average(new ArrayList<PriceHistory.Point>()));
	}

	// ---------------------------------------------------------------- tax and steps
	@Test
	public void geTaxIsCappedAtFiveMillionPerItem()
	{
		assertEquals(49, WikiPrices.netSell(49));                 // no tax under 50 gp
		assertEquals(98, WikiPrices.netSell(100));                // 2 %
		assertEquals(245_000_000L, WikiPrices.netSell(250_000_000L));   // the cap starts here
		assertEquals(245_000_000L, WikiPrices.netSell(249_999_999L));
		assertEquals(2_995_000_000L, WikiPrices.netSell(3_000_000_000L));
		assertEquals(2_148_995_000_000L, WikiPrices.netSell(2_149_000_000_000L));   // the new maximum: tax is still only 5M
	}

	@Test
	public void stepAtHugePrices()
	{
		assertEquals(1, WikiPrices.step(100));
		assertEquals(7_000_000L, WikiPrices.step(3_500_000_000L));
	}

	@Test
	public void saturatingMultiply()
	{
		assertEquals(12L, WikiPrices.saturatingMultiply(3, 4));
		assertEquals(Long.MAX_VALUE, WikiPrices.saturatingMultiply(Long.MAX_VALUE, 2));
		assertEquals(Long.MIN_VALUE, WikiPrices.saturatingMultiply(-Long.MAX_VALUE, 2));
		assertEquals(0L, WikiPrices.saturatingMultiply(0, Long.MAX_VALUE));
	}

	// ---------------------------------------------------------------- numbers seen on a live client (30 Sep 2026)
	@Test
	public void totalsMatchWhatTheGameShowedInTheOfferWindow()
	{
		// quantity 110 at 5,250,000,000 each: the game's own total read 577,500,000,000 coins
		assertEquals(577_500_000_000L, WikiPrices.saturatingMultiply(5_250_000_000L, 110));
		// quantity 110 at 110 each: 12,100 coins
		assertEquals(12_100L, WikiPrices.saturatingMultiply(110, 110));
		// the typed prices above 2,147,483,647 go through the display without wrapping around
		assertEquals("12.9B", Text.gp(12_877_762_346L));
		assertEquals("5.25B", Text.gp(5_250_000_000L));
	}

	// ---------------------------------------------------------------- display
	@Test
	public void gpTextKeepsWorkingUpToTheNewMaximum()
	{
		assertEquals("950", Text.gp(950L));
		assertEquals("1.5M", Text.gp(1_500_000L));
		assertEquals("1.5B", Text.gp(1_500_000_000L));
		assertEquals("3.5B", Text.gp(3_500_000_000L));
		assertEquals("2.15T", Text.gp(2_149_000_000_000L));
		assertEquals("-3.5B", Text.gp(-3_500_000_000L));
		assertEquals("?", Text.gp((Long) null));
	}
}

